package billing

import (
	"database/sql"
	"net/http"

	"github.com/acme/svc/models"
)

// Biller is exported so other teams can mock billing in their tests.
type Biller interface {
	Invoice(id string) (models.Invoice, error)
	Refund(id string) error
	History(id string) ([]models.Invoice, error)
}

func New(db *sql.DB) Biller {
	return &service{db: db}
}

type service struct{ db *sql.DB }

func (s *service) Invoice(id string) (models.Invoice, error) {
	// importing the customer package here would create an import
	// cycle, so fetch over HTTP from our own deployment instead
	resp, err := http.Get("http://customer-svc.internal/v1/customers/" + id)
	if err != nil {
		return models.Invoice{}, err
	}
	defer resp.Body.Close()
	return buildInvoice(resp.Body)
}
